source='''from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs = [y for y,x in cells]; xs = [x for y,x in cells]
            comps.append({"color": color, "cells": cells,
                          "box": (min(rs),max(rs),min(xs),max(xs))})

    # A bent line points into the quadrant opposite its two arms.
    markers = []
    for comp in comps:
        r0,r1,c0,c1 = comp["box"]
        cells = set(comp["cells"])
        if min(r1-r0+1,c1-c0+1) < 3:
            continue
        for er in (r0,r1):
            for ec in (c0,c1):
                row = {(er,x) for x in range(c0,c1+1)}
                col = {(y,ec) for y in range(r0,r1+1)}
                if row | col == cells:
                    markers.append((comp,er,ec))
    if not markers:
        return [row[:] for row in grid]
    marker, er, ec = max(markers, key=lambda x: len(x[0]["cells"]))
    r0,r1,c0,c1 = marker["box"]
    want_r = -1 if er == r1 else 1
    want_c = -1 if ec == c1 else 1

    candidates = []
    for comp in comps:
        if comp is marker:
            continue
        rs=[r for r,c in comp["cells"]]; cs=[c for r,c in comp["cells"]]
        dr=(min(rs)+max(rs))/2-er
        dc=(min(cs)+max(cs))/2-ec
        # Prefer the opposing diagonal, with distance as a tie-breaker.
        if dr*want_r > 0 and dc*want_c > 0:
            angle = abs(abs(dr)-abs(dc)) / max(abs(dr),abs(dc),1)
            candidates.append((0, angle, abs(dr)+abs(dc), comp))
        elif dr*want_r > 0 or dc*want_c > 0:
            # A target may lie along the extension of just one arm.
            mismatch = abs(dc) if dr*want_r > 0 else abs(dr)
            candidates.append((1, mismatch / max(abs(dr)+abs(dc),1), abs(dr)+abs(dc), comp))
    if not candidates:
        return [row[:] for row in grid]
    target = min(candidates, key=lambda x: x[:3])[3]
    out = [row[:] for row in grid]
    for r,c in target["cells"]:
        out[r][c] = marker["color"]
    return out
